    "bd.title": "String Art — Byg viklemaskinen",
    "bd.meta": "Byg String Arts viklemaskine: en 3D-model, delene der skal købes, dele til 3D-print, boreplaner, ledningsdiagram, styringens indstillinger og samling trin for trin.",
    "bd.sub": "byg maskinen",
    "bd.toMachine": "Maskine",
    "bd.h1": "Byg viklemaskinen",
    "bd.intro": "En drejeskive bærer sømpladen; en trådguide over kanten bevæger sig kun ind og ud og op og ned. Alt her er regnet ud fra ét sæt mål, til en sømcirkel på 600 mm med 240 søm: 3D-modellen, de printede dele, boreplanerne og styringens indstillinger. Maskinsiden planlægger bevægelserne og skriver G-koden.",
    "bd.loading": "Indlæser 3D-modellen…",
    "bd.pickHint": "Klik på en del for at se, hvad den er. Træk for at dreje, rul for at zoome.",
    "bd.turn": "Drej langsomt",
    "bd.h.numbers": "Tallene",
    "bd.h.buy": "Dele der skal købes",
    "bd.h.print": "Dele der skal printes",
    "bd.printHint": "Hver fil er drejet, så den printer bedst, og ligger på printpladen. Lag på 0,2 mm, medmindre noten siger andet. FreeCAD-modellen rummer alle dele og kan ændres.",
    "bd.fcstd": "FreeCAD-model (.FCStd)",
    "bd.h.drill": "Boreplaner",
    "bd.svgBase": "Plan over bunden i naturlig størrelse (SVG)",
